steps.script:
GameState.state["factions"]["2"]["detachment"] = "Aquilan Shield"
GameState.state.players["1"]["cp"] = 0
GameState.state.players["2"]["cp"] = 0
SettingsService.set("auto_allocate_wounds", true)
var xs := [807.0, 880.0, 952.0]
var ms = GameState.state.units["U_CUSTODIAN_GUARD_D"].models
for i in range(ms.size()):
	ms[i]["position"] = {"x": xs[i % 3], "y": 1316.0}
tree.current_scene._recreate_unit_visuals()
return load("res://scripts/codex/custodes/CustodesDetachments.gd").within_objective_range(GameState.state.units["U_CUSTODIAN_GUARD_D"])

var ph = PhaseManager.get_current_phase_instance()
var n := 0
for d in ph.dice_log:
	if str(d.get("context", "")) == "to_wound":
		for e in d.get("modifier_ledger", []):
			if str(e.get("source", "")).begins_with("Gilded Guardians"):
				print("[cus11e aquilan] ", e)
				n += 1
return n

var panel = tree.root.get_node("Main").get_node_or_null("HUD_Left/GameLogPanel")
if panel == null:
	for n in tree.root.get_node("Main").find_children("*", "", true, false):
		if n.get("_tab_dice_button") != null:
			panel = n
			break
if panel == null:
	return "panel not found"
panel._tab_dice_button.emit_signal("pressed")
return true
